  }
  enqueue(edit) {
    const { document_id } = edit;
    if (!this.buffers.has(document_id)) this.buffers.set(document_id, []);
    // insert into per-doc heap with key = edit.clock
  }
  tryCommit(document_id) {
    // commit edits in order if their clocks are contiguous with frontier
  }
}
```

