type Event struct{ Tenant string; Seq uint64; Data string }

func main() {
  global := make(chan Event, 8) // bounded global queue
  tenants := map[string]chan Event{
    "tA": make(chan Event, 4),
    "tB": make(chan Event, 4),
  }
  // enqueue example (producer)
  go func(){ global <- Event{Tenant:"tA", Seq:1, Data:"x"} }()
  // dispatcher (simplified)
